using System;using System.Linq;using System.IO;using Game.Configs;using Game.Skirmish.Contracts;using Newtonsoft.Json.Linq;
namespace Game.Runtime{internal static class SourceDeclaredMissionConfiguration {
 internal static JObject Context(JObject request)=>SourceConfigurationQualification.Context(request);
 internal static SkirmishScenarioDefinitionConfig Configure(JObject request,SourceConfigMaterializer values){var context=Context(request);var typed=request["typed_mission_configuration"]as JObject;string[] keys={"profiles","campaign_source_path","layout"};if(typed==null||typed.Count!=keys.Length||typed.Properties().Any(p=>!keys.Contains(p.Name))||typed["campaign_source_path"]?.Type!=JTokenType.String)throw new InvalidDataException("Exact per-definition source/layout/profile configuration required");var p=typed["profiles"]as JObject;string[] profiles={"objective","army","start","economy","upgrades","intel","roles"};if(p==null||p.Count!=profiles.Length||p.Properties().Any(x=>!profiles.Contains(x.Name)||x.Value.Type!=JTokenType.String))throw new InvalidDataException("Exact typed profile references required");var layout=values.LogicalLayout(JObject.Parse(System.Text.Encoding.UTF8.GetString(AutonomousWorld.Descriptor(typed["layout"],1024*1024)),new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error}));if(layout.DeclaredConfiguration==null||layout.WorldBinding.HasMeasuredDeployments||layout.WorldBinding.BindAllConfigurations)throw new InvalidDataException("Explicit single declared configuration, never measured/all-config promotion required");var source=values.ByPath<OperationMapDefinition>((string)typed["campaign_source_path"]);if(source.OperationMapId!=(string)context["target_context"]["operation_map_id"]||source.ContentHash!=(string)context["target_context"]["source_content_hash"])throw new InvalidDataException("Actual definition-referenced Campaign source changed");var d=new SkirmishScenarioDefinitionConfig();d.Configure((string)request["mission_id"],values.ByPath<SkirmishObjectiveConfig>((string)p["objective"]),values.ByPath<SkirmishArmyProfileConfig>((string)p["army"]),values.ByPath<SkirmishStartPackageConfig>((string)p["start"]),values.ByPath<SkirmishEconomyConfig>((string)p["economy"]),values.ByPath<SkirmishUpgradeConfig>((string)p["upgrades"]),values.ByPath<SkirmishIntelConfig>((string)p["intel"]),values.ByPath<SkirmishRoleCatalogConfig>((string)p["roles"]),layout);d.BindCampaignMap(source);SourceDeclaredMissionLogicalBindingReference.Bind(request["mission_logical_binding"]as JObject,d,request);return d;}
 internal static int RequireHonestSourceOnlyCatalog(SkirmishBattleCatalogConfig catalog,string id){if(catalog==null||!catalog.TryGet(id,out var row)||row.Status!=SkirmishBattleCatalogStatus.Planned||row.PlayableScenarioIndex!=-1||row.IsPlayable||SkirmishMissionDispatch.TryGetLegacyIndex(id,out _))throw new InvalidDataException("Actual canonical Planned/-1 source-only identity required");return -1;}
}}
